(function () {
    var NOTIFICATIONS_LIST = ["Старые диалоговые окна", "Смена формы и цветов минимапы \"/radar\"", "Смена размера логотипа сервера \"/logo\"", "Старая карточка бизнесов, имущества" , "interfaceLoader by trustov"];
    var DURATION_MS = 3500;
    var BASE_BOTTOM_VH = 2.5;
    var STEP_VH = 6.5;
    var RETRIES = 6;
    var RETRY_DELAY = 1500;
    var SHOW_DELAY = 4000;

    function createNotificationElement(text, index) {
        var parent = document.body || document.documentElement;
        if (!parent) return false;

        var uniqueIdShadow = 'ep-init-notification-shadow-' + index;
        var uniqueIdBox = 'ep-init-notification-' + index;

        if (!document.getElementById('ep-notify-styles')) {
            var styleEl = document.createElement('style');
            styleEl.id = 'ep-notify-styles';
            styleEl.textContent = '@keyframes epNotifyFade { 0% { opacity: 0; transform: translateY(10px); } 10% { opacity: 1; transform: translateY(0); } 85% { opacity: 1; transform: translateY(0); } 100% { opacity: 0; transform: translateY(-10px); } }';
            (document.head || parent).appendChild(styleEl);
        }

        var durationSec = (DURATION_MS / 1000).toFixed(2);
        var bottomPos = BASE_BOTTOM_VH + (index * STEP_VH);

        var shadow = document.createElement('div');
        shadow.id = uniqueIdShadow;
        shadow.style.cssText = [
            'position: fixed !important;',
            'right: 0 !important;',
            'bottom: ' + bottomPos + 'vh !important;',
            'width: 45vh !important;',
            'height: 28vh !important;',
            'pointer-events: none !important;',
            'z-index: 2147483646 !important;',
            'animation: epNotifyFade ' + durationSec + 's ease-in-out forwards !important;'
        ].join(' ');

        var box = document.createElement('div');
        box.id = uniqueIdBox;
        box.textContent = text;
        box.style.cssText = [
            'position: fixed !important;',
            'right: 2.5vh !important;',
            'bottom: ' + bottomPos + 'vh !important;',
            'background: rgba(0, 0, 0, 0.7) !important;',
            'color: #ffffff !important;',
            'padding: 1.2vh 2.8vh !important;',
            'border-radius: 0.3vh !important;',
            'font-family: "GothamPro Medium"; ',
            'font-size: 1.6vh !important;',
            'line-height: 1.3 !important;',
            'text-align: center !important;',
            'display: flex !important;',
            'align-items: center !important;',
            'justify-content: center !important;',
            'box-shadow: none !important;',
            'border: none !important;',
            'outline: none !important;',
            'z-index: 2147483647 !important;',
            'pointer-events: none !important;',
            'user-select: none !important;',
            'animation: epNotifyFade ' + durationSec + 's ease-in-out forwards !important;'
        ].join(' ');

        parent.appendChild(shadow);
        parent.appendChild(box);

        setTimeout(function () {
            if (shadow.parentNode) shadow.parentNode.removeChild(shadow);
            if (box.parentNode) box.parentNode.removeChild(box);
        }, DURATION_MS + 100);
        return true;
    }

    function renderAll() {
        var ok = true;
        NOTIFICATIONS_LIST.forEach(function (text, index) {
            if (text && text.trim()) {
                if (!createNotificationElement(text, index)) ok = false;
            }
        });
        return ok;
    }

    function boot(attempt) {
        setTimeout(function () {
            if (window.__epInitNotifShown) return;
            var parent = document.body || document.documentElement;
            if (!parent && attempt < RETRIES) {
                boot(attempt + 1);
                return;
            }
            if (renderAll()) {
                window.__epInitNotifShown = true;
            } else if (attempt < RETRIES) {
                boot(attempt + 1);
            }
        }, attempt === 0 ? SHOW_DELAY : RETRY_DELAY);
    }

    boot(0);
})();

